// Detalle de cada botón del reporte, desde v_reporte_lider (SQL). La IA no interviene.
// Salida: un mensaje de encabezado y, para pendientes, un mensaje por caso con sus botones.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const corta = (s, n) => { s = String(s ?? ''); return s.length > n ? s.slice(0, n) + '…' : s; };
const arr = (v) => Array.isArray(v) ? v : (typeof v === 'string' ? JSON.parse(v || '[]') : []);
const obj = (v) => (v && typeof v === 'object') ? v : (typeof v === 'string' ? JSON.parse(v || '{}') : {});
const dur = (m) => { m = Math.abs(Number(m)); return m >= 60 ? Math.round(m / 60) + ' h' : m + ' min'; };
const plazo = (m) => (m === null || m === undefined) ? 'por confirmar' : (Number(m) < 0 ? 'vencido hace ' + dur(m) : 'vence en ' + dur(m));
const q = $('Interpretar acción').first().json;
const r = $('Leer reporte (detalle)').first().json || {};
const periodo = obj(r.kpis).periodo || 'últimas 24 h';
const chat = q.chat_id;
const out = [];
const T = (m) => out.push({ json: { tipo: 'texto', chat_id: chat, mensaje: m } });
const itemResp = (x) => ({ json: { tipo: 'aprobar', chat_id: chat, respuesta_id: x.id, numero_caso: x.caso,
  mensaje: '✍️ <b>' + (x.tipoResp === 'comunicado' ? 'Comunicado' : 'Respuesta') + ' · Caso #' + x.caso + '</b> · ' + esc(x.sev) + ' ' + esc(x.pais) + ' · ' + esc(plazo(x.min)) +
    '\n' + esc(x.cliente) + ' · ' + esc(x.asunto) + '\n<blockquote>' + esc(corta(x.texto, 2500)) + '</blockquote>\nEste es el texto exacto que recibiría el cliente.' } });
const pie = '\n\n💬 Pregunta por uno: <code>caso 1058</code> y tu pregunta.';
switch (q.clave) {
  case 'sla': {
    const l = arr(r.sla_riesgo);
    if (!l.length) { T('⏱ <b>SLA en riesgo</b>\n\n✅ Ningún caso pendiente supera el 80 % de su SLA.'); break; }
    T('⏱ <b>SLA vencidos o en riesgo (' + l.length + ')</b>\nDel más urgente al menos urgente. Cada caso trae el texto que se enviaría y sus botones.');
    for (const x of l.slice(0, 5)) out.push(itemResp({ id: x.respuesta_id, caso: x.caso, sev: x.severidad, pais: x.pais, cliente: x.cliente, asunto: x.asunto, tipoResp: x.tipo, min: x.min_restantes, texto: x.texto }));
    if (l.length > 5) T('…y ' + (l.length - 5) + ' más. Escribe <code>caso NNNN</code> para verlos.');
    break;
  }
  case 'pen': {
    const l = arr(r.decisiones);
    if (!l.length) { T('✍️ <b>Pendientes</b>\n\n✅ Nada pendiente de tu decisión.'); break; }
    const nA = l.filter(d => d.tipo === 'aprobar').length, nE = l.length - nA;
    T('✍️ <b>Necesita tu decisión (' + l.length + ')</b>\n' + nA + ' textos por aprobar · ' + nE + ' escalamientos por confirmar. Ordenados por urgencia.');
    for (const d of l.slice(0, 6)) {
      if (d.tipo === 'aprobar') out.push(itemResp({ id: d.id, caso: d.numero_caso, sev: d.severidad, pais: d.pais, cliente: d.cliente, asunto: d.asunto, tipoResp: /comunicado/i.test(d.etiqueta) ? 'comunicado' : 'respuesta', min: d.min_restantes, texto: d.texto }));
      else out.push({ json: { tipo: 'escalar', chat_id: chat, escalamiento_id: d.id, numero_caso: d.numero_caso,
        mensaje: '🛠 <b>Escalamiento por confirmar · Caso #' + d.numero_caso + '</b> · ' + esc(d.severidad) + ' ' + esc(d.pais) +
          '\n' + esc(d.cliente) + ' · ' + esc(d.asunto) + '\nFicha: ' + esc(d.texto) + '\nConfirmar envía la ficha por correo a Ingeniería.' } });
    }
    if (l.length > 6) T('…y ' + (l.length - 6) + ' más. Escribe <code>caso NNNN</code> para verlos.');
    break;
  }
  case 'res': {
    const l = arr(r.resueltos);
    if (!l.length) { T('✅ <b>Resueltos</b> · ' + esc(periodo) + '\n\nTodavía no se ha enviado ninguna respuesta en este periodo.'); break; }
    const ok = l.filter(x => x.cumple_sla).length;
    const linea = (x) => (x.cumple_sla ? '🟢' : '🔴') + ' #' + x.caso + ' · ' + esc(x.severidad) + ' ' + esc(x.pais) + ' · ' + esc(corta(x.cliente, 28)) +
      '\n   respondido en ' + dur(x.min_respuesta) + ' (' + esc(x.enviado) + ')' + (x.cumple_sla ? '' : ' · fuera de SLA');
    const ing = l.filter(x => x.situacion === 'en_ingenieria');
    const cer = l.filter(x => x.situacion !== 'en_ingenieria');
    let t = '✅ <b>Resueltos (' + l.length + ')</b> · ' + esc(periodo) + '\n' + ok + ' de ' + l.length + ' respondidos dentro del SLA (🟢 dentro · 🔴 fuera).';
    if (ing.length) t += '\n\n🛠 <b>Respondidos al cliente, siguen en Ingeniería (' + ing.length + ')</b>\n' + ing.slice(0, 8).map(linea).join('\n');
    if (cer.length) t += '\n\n📬 <b>Cerrados con la respuesta enviada (' + cer.length + ')</b>\n' + cer.slice(0, 10).map(linea).join('\n');
    if (ing.length > 8 || cer.length > 10) t += '\n…y más. Escribe <code>caso NNNN</code> para ver uno.';
    T(t + pie);
    break;
  }
  case 'inc': {
    const l = arr(r.incidentes);
    if (!l.length) { T('🚨 <b>Incidentes</b>\n\n✅ No hay incidentes abiertos.'); break; }
    T('🚨 <b>Incidentes abiertos (' + l.length + ')</b>\n\n' + l.map(i =>
      '<b>' + (i.firma === 'fuente_externa' ? 'Fuente externa' : 'Plataforma') + '</b> · ' + esc(i.producto) + ' ' + esc(i.pais) + (i.codigo ? ' · ' + esc(i.codigo) : '') +
      '\n' + (i.casos || []).length + ' casos (' + (i.casos || []).map(c => '#' + c).join(', ') + ') · desde ' + esc(i.desde) + (Number(i.oleadas) > 1 ? ' · ' + i.oleadas + ' oleadas' : '') +
      '\n👉 ' + esc(i.accion)).join('\n\n') + pie);
    break;
  }
  case 'pat': {
    const l = arr(r.patrones);
    if (!l.length) { T('🔁 <b>Patrones</b> · ' + esc(periodo) + '\n\nNo hay patrones repetidos en este periodo.'); break; }
    const nom = { truora: 'plataforma', fuente_externa_gobierno: 'fuente del gobierno', meta_whatsapp: 'Meta / WhatsApp', integracion_cliente: 'integración del cliente', usuario_final: 'usuario final', no_aplica: 'sin falla', indeterminado: 'origen indeterminado' };
    const bonito = (p) => String(p || '').split(' · ').map(x => nom[x] || x.replace(/_/g, ' ')).join(' · ');
    T('🔁 <b>Patrones y a dónde llevarlos</b> · ' + esc(periodo) + '\nEl destino lo fija una regla en SQL según el origen.\n\n' + l.map(p =>
      '• ' + esc(bonito(p.patron)) + ' · ' + p.tickets + ' casos (' + (p.casos || []).map(c => '#' + c).join(', ') + ')\n   → <b>' + esc(p.destino) + '</b>').join('\n') + pie);
    break;
  }
  case 'gra': {
    const g = obj(obj(r.ultimo_resumen).graficas);
    const urls = arr(g.urls);
    if (urls.length < 4) { T('📊 Aún no hay gráficas guardadas. Se generan con el resumen de la mañana.'); break; }
    out.push({ json: { tipo: 'album', chat_id: chat, urls, caption: '📊 <b>Gráficas del reporte</b> · ' + esc(obj(r.ultimo_resumen).creado) } });
    break;
  }
  case 'txt': {
    const u = obj(r.ultimo_resumen);
    let t = esc(corta(u.texto || 'Aún no hay lectura del día.', 3500));
    for (const s of ['Estado:', 'SLA en riesgo:', 'Incidentes:', 'Patrones:', 'Calidad de la IA:', 'Prioridad de hoy:']) t = t.split(s).join('<b>' + s + '</b>');
    T('📝 <b>Lectura del día · ' + esc(u.creado || '') + '</b>\n\n' + t);
    break;
  }
  default:
    T('Puedes abrir: <code>pendientes</code>, <code>resueltos</code>, <code>sla</code>, <code>incidentes</code>, <code>patrones</code>, <code>graficas</code> o <code>resumen</code>. Escribe <code>reporte</code> para actualizarlo.');
}
